import { describe, expect, it } from 'vitest';
import fixtures from './__fixtures__/parity-fixtures.json';
import { decodeChain, encodeChain, makeSlot, sanitizeParams, kindSpec } from './catalog';
import { renderChain, StudioFxChainProcessor } from './chain';
import catalog from './catalog.json';

const SAMPLE_RATE = fixtures.sampleRate;

/**
 * The fixture is generated by the Kotlin engine that NC Studio and NC Phone
 * Beat run. A failure here means the web app would render a shared rack
 * differently from the app that made it, which is exactly the sonic loss this
 * suite exists to prevent.
 */
describe('studio FX parity with the shared Kotlin engine', () => {
  const input = Float32Array.from(fixtures.input);

  it('has one case per module plus a full chain', () => {
    expect(fixtures.cases.length).toBe(catalog.kinds.length + 1);
  });

  for (const testCase of fixtures.cases) {
    it(`matches the Kotlin renderer: ${testCase.name}`, () => {
      const slots = decodeChain(testCase.chain);
      expect(slots).not.toBeNull();
      const output = renderChain(input, 1, SAMPLE_RATE, slots!, 120);
      const expected = testCase.output;
      expect(output.length).toBe(expected.length);
      let maxDiff = 0;
      let maxIndex = 0;
      for (let i = 0; i < expected.length; i++) {
        const diff = Math.abs(output[i] - expected[i]);
        if (diff > maxDiff) {
          maxDiff = diff;
          maxIndex = i;
        }
      }
      // Float32 emulation matches the JVM closely; this bound is about 20 dB
      // below the quietest 16-bit LSB and far below audibility.
      expect(
        maxDiff,
        `${testCase.name}: sample ${maxIndex} differs by ${maxDiff.toExponential(2)}`,
      ).toBeLessThan(2e-3);
    });
  }
});

describe('studio FX catalog and chain codec', () => {
  it('loads every documented module with valid parameter ranges', () => {
    expect(catalog.schema).toBe('nc.studio-fx-catalog.v1');
    for (const kind of catalog.kinds) {
      expect(kind.params.length).toBeGreaterThan(0);
      for (const param of kind.params) {
        expect(param.max).toBeGreaterThanOrEqual(param.min);
        expect(param.default).toBeGreaterThanOrEqual(param.min);
        expect(param.default).toBeLessThanOrEqual(param.max);
      }
    }
  });

  it('round trips a chain exactly, including bypassed slots', () => {
    const slots = [
      { ...makeSlot('NEVE_1073', { driveDb: 9.5 }), id: 'a' },
      { ...makeSlot('FET_1176', { ratio: 8 }), id: 'b', enabled: false },
      { ...makeSlot('TAPE_MACHINE', { speedIps: 30 }), id: 'c' },
      { ...makeSlot('PLATE_REVERB', { mix: 0.42 }), id: 'd' },
    ];
    const decoded = decodeChain(encodeChain(slots));
    expect(decoded).toEqual(slots);
  });

  it('rejects unknown schemas and drops unknown modules', () => {
    expect(decodeChain({ schema: 'nc.studiofx.v0', chain: [] })).toBeNull();
    const slots = decodeChain({
      schema: 'nc.studiofx.v1',
      chain: [
        { kind: 'FUTURE_MODULE', params: {} },
        { id: 'x', kind: 'TRIM', params: { gainDb: 6, future: 2 } },
      ],
    });
    expect(slots).toHaveLength(1);
    expect(slots![0].params.gainDb).toBe(6);
    expect(slots![0].params.future).toBeUndefined();
  });

  it('clamps values rather than exporting an unreachable control position', () => {
    const params = sanitizeParams('FET_1176', { ratio: 999, attackUs: 1 });
    expect(params.ratio).toBe(20);
    expect(params.attackUs).toBe(20);
  });

  it('keeps module state when only a parameter moves', () => {
    const rack = new StudioFxChainProcessor(SAMPLE_RATE, 120);
    const slot = makeSlot('TAPE_MACHINE');
    rack.setChain([slot]);
    const out = new Float32Array(2);
    // Longer than the tape module's 4 ms modulated delay, so it has signal.
    for (let i = 0; i < 512; i++) rack.processInto(0.1, 0.1, out);
    const before = out[0];
    rack.setChain([{ ...slot, params: { ...slot.params, driveDb: slot.params.driveDb + 1 } }]);
    rack.processInto(0.1, 0.1, out);
    // A rebuilt module would start from silence; the live one must not.
    expect(Math.abs(out[0] - before)).toBeLessThan(0.2);
    expect(out[0]).not.toBe(0);
  });
});
